Q: How to calculate matrix determinant? n*n or just 5*5 A: <pre><code>#include &lt;stdio.h&gt;
#include &lt;math.h&gt;
#include &lt;stdlib.h&gt;


int det(int, int*);



int arr[5][5] = {
    {2,4,9,1,2},
    {6,3,4,2,6},
    {5,7,8,6,9},
    {9,1,5,3,3},
    {3,2,5,3,9}
};



int main(void)
{







    int* p = &amp;arr[0][0];


    printf(&quot;value of determinant is %d\n&quot;, det(5, p));//4660 
    return 0;
}


int det(int a, int* p)
{
    int i, j, k, counter;
    int resultOfSubStep = 0;
    int* p1 = NULL;

    if (a &gt; 2)
    {
        p1 = (int*)malloc(a * a * sizeof(int));


        for (i = 0; i &lt; a; i++) {

            counter = 0;
            for (j = 0; j &lt; a - 1; j++)
            {

                for (k = 0; k &lt; a; k++) {
                    if (k == i)continue;

                    *(p1 + counter) = *(p + a * (j + 1) + k);

                    counter++;
                }

            }


            int k1 = *(p + i);
            if (k1 != 0)
            {
                k1 = k1 * det(a - 1, p1);
                resultOfSubStep += k1 * ((i % 2 == 0) ? 1 : -1); //pow(-1, i);
            }
        }
        free(p1);
        return resultOfSubStep;
    }
    else if (a == 2)
    {

        return (*p) * (*(p + 3)) - *(p + 1) * (*(p + 2));

    }
    else return *p;
}
</code></pre>

Q: How can I organize a vector of structs by a key when I know the vector size and all existing key values? A: <p>You can take advantage of the fact that the Vec contains (in essence) exactly the indices <code>0..(n-1)</code> to sort in place in <code>O(n)</code> time:</p>
<pre class="lang-rust prettyprint-override"><code>#[derive(Debug, Clone, Copy)]
enum TestEnum {
    Foo,
    Bar,
    Baz,
}

#[derive(Debug)]
struct TestStruct {
    key: TestEnum,
    val: u32,
}

impl TestStruct {
    fn as_index(&amp;self) -&gt; usize {
        self.key as usize
    }
}

fn sort_in_place(items: &amp;mut [TestStruct]) {
    for i in 0..items.len() {
        while items[i].as_index() != i {
            items.swap(
                items[i].as_index(),
                items[items[i].as_index()].as_index(),
            );
        }
    }
}

fn main() {
    let mut test_vec = vec![
        TestStruct {
            val: 1,
            key: TestEnum::Bar,
        },
        TestStruct {
            val: 2,
            key: TestEnum::Baz,
        },
        TestStruct {
            val: 3,
            key: TestEnum::Foo,
        },
    ];
    sort_in_place(&amp;mut test_vec);
    println!(&quot;{test_vec:?}&quot;);
}
</code></pre>
<pre class="lang-rust prettyprint-override"><code>[TestStruct { key: Foo, val: 3 }, TestStruct { key: Bar, val: 1 }, TestStruct { key: Baz, val: 2 }]
</code></pre>
<p>It looks <code>O(n^2)</code> (we're doing some seemingly <code>O(n)</code> work once for each index), but in reality what's happening is we move each item at the current index to its correct final position until the current index contains <em>its</em> correct item. Since each item in the Vec is moved at most once (either out of this index to its correct position, or out of an arbitrary location to this index), at most n swaps occur.</p>
